create table xxcus.xxfnd_data_security_rules (
    rule_id               number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    role_code             varchar2(30 byte) not null enable,
    table_name            varchar2(128 byte) not null enable,
    rule_type             varchar2(20 byte) not null enable,
    column_name           varchar2(128 byte),
    value_list            varchar2(4000 byte),
    enabled_flag          varchar2(1 byte) default 'Y' not null enable,
    description           varchar2(1000 byte),
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_data_security_rules
    add constraint xxfnd_data_security_rules_ck1
        check ( rule_type in ( 'ALL_ROWS', 'OWN_RECORDS', 'COLUMN_IN_LIST' ) ) enable;

alter table xxcus.xxfnd_data_security_rules
    add constraint xxfnd_data_security_rules_ck2
        check ( ( rule_type = 'ALL_ROWS'
                  and column_name is null
                  and value_list is null )
                or ( rule_type = 'OWN_RECORDS'
                     and column_name is not null
                     and value_list is null )
                or ( rule_type = 'COLUMN_IN_LIST'
                     and column_name is not null
                     and value_list is not null ) ) enable;

alter table xxcus.xxfnd_data_security_rules
    add constraint xxfnd_data_security_rules_ck3
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_data_security_rules
    add constraint xxfnd_data_security_rules_pk primary key ( rule_id )
        using index enable;


